@block
gi = db2gain(drive)
go = db2gain(output) / gi
@sample
xL = inL * gi
xR = inR * gi
if (side < 0.5) {
  if (xL > 0) { xL = sin(xL * 1.57079634) / 1.57079634 }
  if (xR > 0) { xR = sin(xR * 1.57079634) / 1.57079634 }
} else {
  if (xL < 0) { xL = -(sin(-xL * 1.57079634) / 1.57079634) }
  if (xR < 0) { xR = -(sin(-xR * 1.57079634) / 1.57079634) }
}
outL = xL * go
outR = xR * go
